content.content:
  case SJuxt(_, _, _, front::_, _, true) => writesStaticArgs(front)
  case SMathPrimary(_, _, _, front, _) => writesStaticArgs(front)
  case S_RewriteFnApp(_, f, _) => writesStaticArgs(f)
  case S_RewriteFnRef(_, _, sargs) => !sargs.isEmpty
  case f: FunctionalRef => !f.getStaticArgs.isEmpty
  case SOpExpr(_, f, _) => !f.getStaticArgs.isEmpty
  case m: MethodInvocation => !m.getStaticArgs.isEmpty
  case _ => false
}

/** Signal that no candidate of a call with coercion is more specific than every other. */
private def signalAmbiguity(tied: List[ArrowType], args: List[Either[Expr, FnExpr]])
                           (implicit errorFactory: ApplicationErrorFactory): scala.Unit = {
  val app = errorFactory.app
  if (app == null) {
    errors.signal(errorFactory.makeApplicationError(Nil))
    return
  }
  val kind = app match {
    case S_RewriteFnApp(_, f: FunctionalRef, _) => "call to function %s".format(f.getOriginalName)
    case _: _RewriteFnApp => "function application"
    case o: OpExpr => "call to operator %s".format(o.getOp.getOriginalName)
    case m: MethodInvocation => "method invocation %s.%s".format(errorFactory.recvrType.getOrElse(""), m.getMethod)
    case o: SubscriptExpr => "call to subscript operator %s.%s".format(errorFactory.recvrType.getOrElse(""), o.getOp.unwrap)
    case _ => "call"
  }
  signal(app, "Ambiguous coercion in %s: of the declarations applicable to an argument of type %s only by coercion, none is more specific than every other: %s.".
              format(kind, normalize(getArgType(args)), tied.map(_.toString).mkString("; ")))
}

/** Whether the type is a numeral's own type. */
def isNumeralType(t: Type): Boolean =
  Types.isNumeralType(t)

/**
 * The narrowest default type that holds every numeral of es: RR64 where one
 * has a radix point, its supertype or coercion target of that name, and
 * otherwise numeralReading's ZZ32, ZZ64 or ZZ by their values.
 */
def numeralDefault(es: List[Expr]): Option[Type] =
  if (es.exists(_.isInstanceOf[FloatLiteralExpr])) {
    val from = es.collect { case f: FloatLiteralExpr => f }.flatMap(getType(_)).collect { case t: TraitType => t }.headOption
    from.flatMap(f => (analyzer.ancestors(f).toList.collect { case t: TraitType => t } ++
                       coercions.getCoercionTargetsFrom(f)).find(_.getName.getText == "RR64"))
  }
  else numeralReading(es)

/** The numeral converted into the type t: as it is where it is one, else by its coercion. */
private def numeralInto(e: Expr, t: Type): Option[Expr] =
  if (isSubtype(getType(e).get, t)) Some(e) else coercions.buildCoercion(e, t)

/**
 * The expression with each numeral in its result positions converted into
 * its default: a numeral alone, each element of a tuple on its own, and the
 * branches of an if or case expression, or of a block's last expression,
 * all numerals, together, into the narrowest default that holds them all.
 * Any other expression is returned as it is: the default applies to a
 * numeral, never to an expression of a numeral's type.
 */
def defaultNumeral(e: Expr): Expr = e match {
  case n if NumeralConversion.isNumeral(n) => numeralDefault(List(n)).flatMap(numeralInto(n, _)).getOrElse(n)
  case t@STupleExpr(SExprInfo(span, paren, _), es, None, Nil, inApp) =>
    val nes = es.map(defaultNumeral)
    if (nes.zip(es).forall(p => p._1 eq p._2) || nes.exists(getType(_).isEmpty)) t
    else STupleExpr(SExprInfo(span, paren, Some(NF.makeTupleType(span, toJavaList(nes.map(getType(_).get))))),
                    nes, None, Nil, inApp)
  case _ => joinNumerals(e) match {
    case Some(ns) if ns.nonEmpty => numeralDefault(ns).flatMap(joinInto(e, _)).getOrElse(e)
    case _ => tupleJoin(e).getOrElse(e)
  }
}

/**
 * A join whose every result is a tuple, each tuple's numerals at their
 * defaults: numerals of different values have different types, so the
 * branches meet at one type only once their numerals take their defaults.
 */
private def tupleJoin(e: Expr): Option[Expr] = {
  def block(b: Block): Option[Block] = tupleJoin(b).map(_.asInstanceOf[Block])
  def same(ts: List[Type]): Option[Type] =
    if (ts.nonEmpty && ts.forall(t => isSubtype(t, ts.head) && isSubtype(ts.head, t))) Some(ts.head) else None
  def typed(x: Expr) = getType(x)
  e match {
    case t: TupleExpr =>
      val d = defaultNumeral(t)
      if (d eq t) None else Some(d)
    case SBlock(SExprInfo(sp, p, _), loc, at, wd, es) if es.nonEmpty =>
      tupleJoin(es.last).flatMap(l => typed(l).map(ty => SBlock(SExprInfo(sp, p, Some(ty)), loc, at, wd, es.init :+ l)))
    case SDo(SExprInfo(sp, p, _), List(front)) =>
      block(front).flatMap(f => typed(f).map(ty => SDo(SExprInfo(sp, p, Some(ty)), List(f))))
    case SIf(SExprInfo(sp, p, _), clauses, Some(els)) =>
      for (ne <- block(els);
           ncs <- { val rs = clauses.map { case SIfClause(i, t, b) => block(b).map(SIfClause(i, t, _)) }
                    if (rs.forall(_.isDefined)) Some(rs.map(_.get)) else None };
           ty <- same((ne :: ncs.map(_.getBody)).flatMap(typed(_))))
        yield SIf(SExprInfo(sp, p, Some(ty)), ncs, Some(ne))
    case _ => None
  }
}

def numeralJoinInto(e: Expr, t: Type): Option[Expr] =
  if (NumeralConversion.isNumeral(e) || !numeralResult(e)) None else joinInto(e, t)

/** Whether some result position of the join is a numeral. */
private def numeralResult(e: Expr): Boolean = e match {
  case n if NumeralConversion.isNumeral(n) => true
  case SBlock(_, _, _, _, es) if es.nonEmpty => numeralResult(es.last)
  case SDo(_, List(front)) => numeralResult(front)
  case SIf(_, clauses, Some(els)) => (els :: clauses.map(_.getBody)).exists(numeralResult)
  case SCaseExpr(_, _, _, _, _, clauses, els) => (els.toList ++ clauses.map(_.getBody)).exists(numeralResult)
  case STry(_, body, catchC, _, None) =>
    numeralResult(body) || catchC.exists { case SCatch(_, _, cs) => cs.exists { case SCatchClause(_, _, b) => numeralResult(b) } }
  case SLetExpr(_, body) => numeralResult(body)
  case STupleExpr(_, es, None, Nil, _) => es.exists(numeralResult)
  case _ => false
}

/** The numerals in the result positions of a join whose every result is a numeral. */
private def joinNumerals(e: Expr): Option[List[Expr]] = {
  def all(bs: List[Expr]): Option[List[Expr]] = {
    val rs = bs.map(joinNumerals)
    if (rs.forall(_.isDefined)) Some(rs.flatMap(_.get)) else None
  }
  e match {
    case n if NumeralConversion.isNumeral(n) => Some(List(n))
    case SBlock(_, _, _, _, es) if es.nonEmpty => joinNumerals(es.last)
    case SDo(_, List(front)) => joinNumerals(front)
    case SIf(_, clauses, Some(els)) => all(els :: clauses.map(_.getBody))
    case SCaseExpr(_, _, _, _, _, clauses, els) if clauses.nonEmpty => all(els.toList ++ clauses.map(_.getBody))
    case _ => None
  }
}

/** The join with each numeral in its result positions converted into d, and its type d. */
private def joinInto(e: Expr, d: Type): Option[Expr] = {
  def block(b: Block): Option[Block] = joinInto(b, d).map(_.asInstanceOf[Block])
  def each[A](as: List[A], f: A => Option[A]): Option[List[A]] = {
    val rs = as.map(f)
    if (rs.forall(_.isDefined)) Some(rs.map(_.get)) else None
  }
  e match {
    case n if NumeralConversion.isNumeral(n) => numeralInto(n, d)
    case SBlock(SExprInfo(sp, p, _), loc, at, wd, es) =>
      joinInto(es.last, d).map(l => SBlock(SExprInfo(sp, p, Some(d)), loc, at, wd, es.init :+ l))
    case SDo(SExprInfo(sp, p, _), List(front)) =>
      block(front).map(f => SDo(SExprInfo(sp, p, Some(d)), List(f)))
    case SIf(SExprInfo(sp, p, _), clauses, Some(els)) =>
      for (ne <- block(els);
           ncs <- each(clauses, (c: IfClause) => c match {
             case SIfClause(i, t, b) => block(b).map(SIfClause(i, t, _)) }))
        yield SIf(SExprInfo(sp, p, Some(d)), ncs, Some(ne))
    case SCaseExpr(SExprInfo(sp, p, _), param, cmp, eq, in, clauses, els) =>
      for (ne <- each(els.toList, block);
           ncs <- each(clauses, (c: CaseClause) => c match {
             case SCaseClause(i, m, b, o) => block(b).map(SCaseClause(i, m, _, o)) }))
        yield SCaseExpr(SExprInfo(sp, p, Some(d)), param, cmp, eq, in, ncs, ne.headOption)
    case STry(SExprInfo(sp, p, _), body, catchC, forbid, None) =>
      for (nb <- block(body);
           nc <- catchC match {
             case None => Some(None)
             case Some(SCatch(i, name, cs)) =>
               each(cs, (c: CatchClause) => c match {
                 case SCatchClause(ci, t, b) => block(b).map(SCatchClause(ci, t, _)) })
                 .map(ncs => Some(SCatch(i, name, ncs)))
           })
        yield STry(SExprInfo(sp, p, Some(d)), nb, nc, forbid, None)
    // a block's last element after a local declaration is the declaration's body
    case SLocalVarDecl(SExprInfo(sp, p, _), body, lhs, rhs) if !body.getExprs.isEmpty =>
      block(body).map(b => SLocalVarDecl(SExprInfo(sp, p, Some(d)), b, lhs, rhs))
    case SLetFn(SExprInfo(sp, p, _), body, fns) if !body.getExprs.isEmpty =>
      block(body).map(b => SLetFn(SExprInfo(sp, p, Some(d)), b, fns))
    // a tuple converts element by element, each element where it stands
    case t@STupleExpr(SExprInfo(sp, p, _), es, None, Nil, inApp) => d match {
      case STupleType(_, ds, None, Nil) if ds.size == es.size =>
        val nes = es.zip(ds).map { case (x, xt) =>
          if (numeralResult(x)) joinInto(x, xt)
          else if (getType(x).exists(isSubtype(_, xt))) Some(x)
          else coercions.buildCoercion(x, xt) }
        if (nes.forall(_.isDefined)) Some(STupleExpr(SExprInfo(sp, p, Some(d)), nes.map(_.get), None, Nil, inApp))
        else None
      case _ => if (getType(t).exists(isSubtype(_, d))) Some(t) else None
    }
    // a result that already has the type stays as it is
    case x if !NumeralConversion.isNumeral(x) && !numeralResult(x) && getType(x).exists(t => isSubtype(t, d)) => Some(x)
    case _ => None
  }
}

/** Whether a numeral's default could change the expression. */
private def mayDefault(e: Expr): Boolean = e match {
  case _: IntLiteralExpr | _: FloatLiteralExpr | _: TupleExpr | _: If | _: CaseExpr | _: Do => true
  case _ => false
}

def defaultAtUnfixed(e: Expr, p: Type): Expr =
  if (!mayDefault(e) || isNumeralType(p)) e
  else {
    val d = defaultNumeral(e)
    if ((d ne e) && getType(d).exists(isSubtype(_, p))) d else e
  }

/** defaultAtUnfixed for each argument at its parameter type. */
private def defaultAtUnfixedEach(args: List[Expr], domain: Type): List[Expr] =
  if (!args.exists(mayDefault)) args
  else {
    val ps = zipWithDomain(args, domain)
    if (ps.size != args.size) args else ps.map { case (e, p) => defaultAtUnfixed(e, p) }
  }

def defaultFits(e: Expr, p: Type): Option[Expr] =
  if (!mayDefault(e)) None
  else {
    val d = defaultNumeral(e)
    if ((d ne e) && getType(d).exists(isSubtype(_, p))) Some(d) else None
  }

/**
 * A numeral written as a dotted receiver takes its default where the
 * default type has the member; otherwise it stays, as for the prelude's
 * own (1).asNN32.
 */
def defaultReceiver(e: Expr, has: Type => Boolean): Expr =
  if (!NumeralConversion.isNumeral(e)) e
  else {
    val d = defaultNumeral(e)
    if ((d ne e) && getType(d).exists(has)) d else e
  }

/**
 * The arguments of a call before its inference by subtyping, each numeral
 * given its default where nothing else fixes a type: at a parameter whose
 * type is a bare type parameter that numerals alone fix and no other
 * parameter type mentions, with no expected type, the narrowest default
 * that holds them all; and at a parameter of the numeral's own default
 * type, that default, which ranks as no coercion, so that the declaration
 * fits the numeral as it is.
 */
private def preDefault(arrow: ArrowType,
                       context: Option[Type],
                       args: List[Either[Expr, FnExpr]]): List[Either[Expr, FnExpr]] = {
  if (!args.exists(_.left.toOption.exists(NumeralConversion.isNumeral))) return args

        // If there is a declared return type, check the body, expecting this
        // type. If this is a setter, check that the return type is a void too.
        case Some(rt) =>
          if (NU.isSetter(f))
            isSubtype(rt, Types.VOID, f, "Setter declarations must return void.")
          (Some(rt), newChecker.checkExpr(body, rt, errorString("Function body",
                                                                "declared return")))

        case None =>
          val newBody =
            if (NU.isCoercion(f)) newChecker.checkExpr(body)
            else newChecker.defaultNumeral(newChecker.checkExpr(body))
          val rt = if (NU.isCoercion(f)) None else getType(newBody)
          (rt, newBody)
      }

      SFnDecl(info,
              SFnHeader(statics, mods, name, wheres, throws,
                        newContract.asInstanceOf[Option[Contract]],
                        params, newReturnType),
              unambiguousName, Some(newBody), implementsUnambiguousName)
    }

    case v@SVarDecl(info, lhses, None) => v

    case d@SVarDecl(info, lhses, Some(rhs))
      if (lhses.length > 1 && rhs.isInstanceOf[TupleExpr] &&
          rhs.asInstanceOf[TupleExpr].getExprs.size == lhses.length) => {
        val pairs =
          (lhses, toListFromImmutable(rhs.asInstanceOf[TupleExpr].getExprs)).zipped.map((lv, r) => toOption(lv.getIdType) match {
            case Some(pt) => pt match {
              case p@SPattern(_,_,_) =>
                bug("Pattern should be desugared away: " + p)
              case t@SType(_) =>
          //System.out.println("Losing rhs: " + r)
                (lv, checkExpr(r, t, errorString("Right-hand side", "declared")))
            }
            case None => lv match {
              case SLValue(info, name, mods, None, mut) =>
                val newR = defaultNumeral(checkExpr(r, None))
                (SLValue(info, name, mods,
                         Some(getType(newR).getOrElse(return node)), mut),
                 newR)
              case _ => return node
            }
          })
        val (newLhses, newRhses) = (pairs.map(_._1), pairs.map(_._2))
        // The new tuple has the type of its checked elements: each name's
        // thunk reads its own type out of it (Thunker.primeVariables).
        val newTypes = newRhses.map(getType(_).getOrElse(return node))
        val newTuple = EF.makeTupleExpr(NU.getSpan(rhs), toJavaList(newRhses))
        SVarDecl(info, newLhses,
                 Some(addType(newTuple, NF.makeTupleType(NU.getSpan(rhs), toJavaList(newTypes)))))
    }

    case d@SVarDecl(info, lhses, Some(rhs)) => {
      // Gather declared types of LHS as a big tuple type.
      val declaredTypes = lhses.flatMap(lv => toOption(lv.getIdType) match {
                                        case Some(pt) => pt match {
                                          case p@SPattern(_,_,_) =>
                                            bug("Pattern should be desugared away: " + p)
                                          case t@SType(_) => Some(t)
                                        }
                                        case None => None
                                        })
      val declaredType =
        if (declaredTypes.length == lhses.length)
          Some(NF.makeMaybeTupleType(NU.getSpan(d), toJavaList(declaredTypes)))
        else
          None
      // Type check the RHS, expecting the declared type.
      val (newLhses, newRhs) = declaredType match {
        // If there is a declared type, just check the RHS expecting that.
        case Some(typ) =>
          //System.out.println("Losing rhs: " + rhs)
          (lhses, checkExpr(rhs, typ, errorString("Right-hand side", "declared")))
        // If there is not a declared type, check the RHS and assign LHS types
        // from that.
        case None =>
          // Check the RHS.
          val newRhs = defaultNumeral(checkExpr(rhs, None))
          val rhsType = getType(newRhs).getOrElse(return node)
          // Get all the LHSes and their corresponding RHS type.
          val lhsAndRhsTypes = lhses match {
            case List(lhs) => List((lhs, rhsType))
            case _ =>
              if (!enoughElementsForType(lhses, rhsType)) {
                signal(node, "Right-hand side has type %s, but left-hand side is a tuple of %d variables.".format(rhsType, lhses.size))
                return node
              }
              zipWithRhsType(lhses, rhsType)
          }
          // Map over the LHS/RHS pairs to create the new list of LHSes.
          val newLhses = lhsAndRhsTypes.map {
            // No type on LHS -- just insert it.
            case (SLValue(info, name, mods, None, mut), rhsType) =>
              SLValue(info, name, mods, Some(rhsType), mut)
            case (lhs, _) => lhs
          }
          // Where some of the names declare a type, the RHS is checked
          // again, expecting each name's type, as where all of them do.
          val checkedRhs =
            if (declaredTypes.isEmpty) newRhs
            else {
              val nameTypes = lhsAndRhsTypes.map {
                case (SLValue(_, _, _, Some(t@SType(_)), _), _) => t
                case (_, rhsType) => rhsType
              }
              checkExpr(rhs, NF.makeTupleType(NU.getSpan(d), toJavaList(nameTypes)),
                        errorString("Right-hand side", "declared"))
            }
          (newLhses, checkedRhs)
        }
      SVarDecl(info, newLhses, Some(newRhs))
    }

    case _ => throw new Error(errorMsg("not yet implemented: ", node.getClass))
  }

  // ---------------------------------------------------------------------------
  // CHECKEXPR IMPLEMENTATION --------------------------------------------------

  def checkExprDecls(expr: Expr, expected: Option[Type]): Expr = expr match {

    case d@SLocalVarDecl(SExprInfo(span, paren,_), body, lhses, None) => {
      // Extend typechecker with new bindings from the RHS types
      val newChecker = this.extend(lhses)
      // Check the LetExpr body.
      val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
      SLocalVarDecl(SExprInfo(span, paren, newType), newBody, lhses, None)
    }

    case d@SLocalVarDecl(SExprInfo(span, paren,_), body, lhses, Some(rhs))
      if (lhses.length > 1 && rhs.isInstanceOf[TupleExpr] &&
          rhs.asInstanceOf[TupleExpr].getExprs.size == lhses.length) => {
        val pairs =
          (lhses, toListFromImmutable(rhs.asInstanceOf[TupleExpr].getExprs)).zipped.map((lv, r) => toOption(lv.getIdType) match {
            case Some(pt) => pt match {
              case p@SPattern(_,_,_) =>
                bug("Pattern should be desugared away: " + p)
              case t@SType(_) =>
          //System.out.println("Losing rhs: " + rhs)
                (lv, checkExpr(r, t, errorString("Right-hand side", "declared")))
            }
            case None => lv match {
              case SLValue(info, name, mods, None, mut) =>
                val newR = defaultNumeral(checkExpr(r, None))
                (SLValue(info, name, mods,
                         Some(getType(newR).getOrElse(return expr)), mut),
                 newR)
              case _ => return expr
            }
          })
        val (newLhses, newRhses) = (pairs.map(_._1), pairs.map(_._2))
        val newRhs = EF.makeTupleExpr(span, toJavaList(newRhses))
        // Extend typechecker with new bindings from the RHS types
        val newChecker = this.extend(newLhses)
        // Check the LetExpr body
        val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
      SLocalVarDecl(SExprInfo(span, paren, newType), newBody, newLhses, Some(newRhs))
    }

    case d@SLocalVarDecl(SExprInfo(span, paren, _), body, lhses, Some(rhs)) => {
      // Gather declared types of LHS as a big tuple type.
      val declaredTypes = lhses.flatMap(lv => toOption(lv.getIdType) match {
                                        case Some(pt) => pt match {
                                          case p@SPattern(_,_,_) =>
                                            bug("Pattern should be desugared away: " + p)
                                          case t@SType(_) => Some(t)
                                        }
                                        case None => None
                                        })
      val declaredType =
        if (declaredTypes.length == lhses.length)
          Some(NF.makeMaybeTupleType(NU.getSpan(d), toJavaList(declaredTypes)))
        else
          None
      // Type check the RHS, expecting the declared type.
      val (newLhses, newRhs) = declaredType match {
        // If there is a declared type, just check the RHS expecting that.
        case Some(typ) =>
          //System.out.println("Losing rhs: " + rhs)
          (lhses, checkExpr(rhs, typ, errorString("Right-hand side", "declared")))
        // If there is not a declared type, check the RHS and assign LHS types
        // from that.
        case None =>
          // Check the RHS.
          val newRhs = defaultNumeral(checkExpr(rhs, None))
          val rhsType = getType(newRhs).getOrElse(return expr)
          // Get all the LHSes and their corresponding RHS type.
          val lhsAndRhsTypes = lhses match {
            case List(lhs) => List((lhs, rhsType))
            case _ =>
              if (!enoughElementsForType(lhses, rhsType)) {
                signal(expr, "Right-hand side has type %s, but left-hand side is a tuple of %d variables.".format(rhsType, lhses.size))
                return expr
              }
              zipWithRhsType(lhses, rhsType)
          }
          // Map over the LHS/RHS pairs to create the new list of LHSes.
          val newLhses = lhsAndRhsTypes.map {
            // No type on LHS -- just insert it.
            case (SLValue(info, name, mods, None, mut), rhsType) =>
              SLValue(info, name, mods, Some(rhsType), mut)
            case (lhs, _) => lhs
          }
          (newLhses, newRhs)
        }
      // Extend typechecker with new bindings from the RHS types
      val newChecker = this.extend(newLhses)
      // Check the LetExpr body.
      val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
      SLocalVarDecl(SExprInfo(span, paren, newType), newBody, newLhses, Some(newRhs))
    }

    case SLetFn(SExprInfo(span, paren, _), body, fns) => {
      // Extend with functions
      val fnIndices = fns.map(new DeclaredFunction(_))
      val newChecker = this.extendWithListOfFunctions(fnIndices)

      // Prime functionals to infer return types.
      Thunker.primeFunctionals(fnIndices, STypeCheckerFactory.makeTryChecker(newChecker))

      // Check the contained body and FnDecls.
      val (newBody, newType) = checkLetBody(newChecker, body, expected).getOrElse(return expr)
      val newFns = fns.map(newChecker.check(_).asInstanceOf[FnDecl])

      SLetFn(SExprInfo(span, paren, newType), newBody, newFns)
    }

    case _ => throw new Error(errorMsg("Not yet implemented: ", expr.getClass))
  }
}

